lemma Advance(a: nat,e: nat,k: nat,aa: nat,t: nat)
    requires k > 0 && e+k <= 127
    requires aa == a/B.Power(2*e) && t == B.Power(e)
    requires 1 <= aa < B.Power(4*k)
    ensures var next := e+(if aa >= B.Power(2*k) then k else 0);
            1 <= a/B.Power(2*next) < B.Power(2*k)
    ensures var next := e+(if aa >= B.Power(2*k) then k else 0);
            (if aa >= B.Power(2*k) then aa/B.Power(2*k) else aa) == a/B.Power(2*next)
    ensures var next := e+(if aa >= B.Power(2*k) then k else 0);
            B.Power(next) == t*(if aa >= B.Power(2*k) then B.Power(k) else 1)

method Inverse(base: nat,modulus: nat) returns (out: M.Outcome)
    requires base < B.Word && modulus < B.Word
    ensures out == (if modulus == 0 then M.Panic(18)
                    else if modulus > 1 && E.Gcd(modulus,base%modulus) != 1 then M.MissingInverse(base,modulus)
                    else M.Value(V.Spec(base,modulus)))
    ensures out.Value? ==> 0 <= out.result < B.Word

lemma TailState(r: nat,a: nat,n: nat,m: nat)
    requires m > 0
    ensures var nextR := if n%2 == 1 then Multiply(r,a)%m else r;
            var nextN := n/2;
            var nextA := if nextN > 0 then Multiply(a,a)%m else a;
            Multiply(nextR,Power(nextA,nextN))%m == Multiply(r,Power(a,n))%m

lemma JoinStep(mode: Mode, inputType: seq<Byte>, outputType: seq<Byte>, values: seq<seq<Byte>>, index: nat, acc: seq<Byte>, c: Context, local: Environment, later: Environment)
    requires index < |values|
    ensures var first := Step(mode,inputType,outputType,values[index],index,acc,c,local);
            var joined := Splice(local,later,|first.context.history|);
            Tail(mode,inputType,outputType,values,index,acc,c,joined) ==
            (if first.Failure? then first else Prepend(first.values,Tail(mode,inputType,outputType,values,index+1,first.accumulator,first.context,later)))

lemma JoinAdmission(mode: Mode, inputType: seq<Byte>, outputType: seq<Byte>, values: seq<seq<Byte>>, initial: seq<Byte>, c: Context, local: Environment, later: Environment)
    ensures var first := Admission(mode,inputType,outputType,initial,c,local);
            var joined := Splice(local,later,|first.context.history|);
            Run(mode,inputType,outputType,values,initial,c,joined) ==
            (if first.Failure? then first else Tail(mode,inputType,outputType,values,0,initial,first.context,later))

lemma Block(n: nat,le: (nat,nat)->bool,source: seq<nat>,width: nat,block: nat)
    requires |source| == n && width > 0 && Order(n,le) && Runs(n,le,source,width) && block*(2*width) < n
    ensures var start := block*(2*width); var middle := Min(start+width,n); var end := Min(start+2*width,n);
                                                                            var merged := Merge(le,source[start..middle],source[middle..end]);
                                                                            Sorted(le,merged) && multiset(merged) == multiset(Range(start,end-start))

lemma StepFacts(mode: Mode, inputType: seq<Byte>, outputType: seq<Byte>, value: seq<Byte>, index: nat, acc: seq<Byte>, c: Context, env: Environment)
    ensures c.history <= Step(mode,inputType,outputType,value,index,acc,c,env).context.history
    ensures var out := Step(mode,inputType,outputType,value,index,acc,c,env);
            Calls(out.context.history) == Calls(c.history) || Calls(out.context.history) == Calls(c.history)+[index]
    ensures var out := Step(mode,inputType,outputType,value,index,acc,c,env);
            out.Success? ==> Calls(out.context.history) == Calls(c.history)+[index]
    ensures var out := Step(mode,inputType,outputType,value,index,acc,c,env);
            out.Success? && mode != Fold ==> out.accumulator == acc
    ensures var out := Step(mode,inputType,outputType,value,index,acc,c,env);
            out.Success? && mode == Map ==> |out.values| == 1
    ensures var out := Step(mode,inputType,outputType,value,index,acc,c,env);
            out.Success? && mode == Filter ==> out.values == [] || out.values == [value]
    ensures var out := Step(mode,inputType,outputType,value,index,acc,c,env);
            out.Success? && mode == Fold ==> out.values == []

lemma JoinStep(k: Config,i: nat,c: T.Context,local: T.Environment,later: T.Environment)
    requires i < |k.values| && Uint(|k.values|)
    ensures var first := Step(k,i,c,local);
            var joined := E.Splice(local,later,|first.context.history|);
            Tail(k,i,c,joined) == (if first.Failed? || first.index != Missing() then first else Tail(k,i+1,first.context,later))

lemma JoinAdmission(k: Config,c: T.Context,local: T.Environment,later: T.Environment)
    requires Uint(|k.values|)
    ensures var admitted := Admission(k,c,local);
            var joined := E.Splice(local,later,|admitted.context.history|);
            Run(k,c,joined) == (if admitted.Failed? then admitted else Tail(k,0,admitted.context,later))

lemma CompareJoin(k: S.Config,i: nat,kept: seq<nat>,j: nat,c: T.Context,a: T.Environment,b: T.Environment)
    requires i < |k.values| && S.Indices(k,kept,i) && j < |kept|
    ensures S.Compare(k,i,kept,j,c,E.Splice(a,b,|T.Ask(S.Query(k,i,kept,j),c,a).context.history|)) ==
            (if T.Ask(S.Query(k,i,kept,j),c,a).reply.Error? then S.CompareFailed(T.Ask(S.Query(k,i,kept,j),c,a).reply.reason,T.Ask(S.Query(k,i,kept,j),c,a).context)
             else if T.Ask(S.Query(k,i,kept,j),c,a).reply.truth then S.Compared(true,T.Ask(S.Query(k,i,kept,j),c,a).context)
             else S.Compare(k,i,kept,j+1,T.Ask(S.Query(k,i,kept,j),c,a).context,b))

lemma JoinStep(k: S.Config,i: nat,kept: seq<nat>,c: T.Context,local: T.Environment,later: T.Environment)
    requires i < |k.values| && S.Indices(k,kept,i)
    ensures var first := F.Step(k,i,kept,c,local);
            var joined := E.Splice(local,later,|first.context.history|);
            S.Tail(k,i,kept,c,joined) == (if first.Failed? then first else S.Tail(k,i+1,first.kept,first.context,later))

lemma JoinAdmission(k: S.Config,c: T.Context,local: T.Environment,later: T.Environment)
    ensures var admitted := F.Admission(k,c,local);
            var joined := E.Splice(local,later,|admitted.context.history|);
            S.Run(k,c,joined) == (if admitted.Failed? then admitted else S.Tail(k,0,[],admitted.context,later))

function Call(index: nat, target: R.Address, self: R.Address, data: seq<Byte>, selector: seq<Byte>,
                env: R.Environment, history: seq<R.Request>): Outcome
    requires |selector| == 4

function Probe(target: R.Address, self: R.Address, data: seq<Byte>, selector: seq<Byte>, expected: seq<Byte>,
                 env: R.Environment, history: seq<R.Request>): Outcome
    requires |selector| == 4 && |expected| == 4

lemma Outcomes(data: seq<Byte>, parameters: seq<seq<Byte>>, self: R.Address, decode: seq<Byte>->M.Decode,
                 env: R.Environment, history: seq<R.Request>)
    requires decode(data).Decoded? ==> M.Wire(decode(data).graph,parameters)
    ensures decode(data).Malformed? ==> M.Spec(data,parameters,self,decode,env,history) == M.Outcome(E.Aborted(E.Error([])),history)
    ensures decode(data).Decoded? ==>
              M.Spec(data,parameters,self,decode,env,history).history == history+[R.Call(self,M.CallData(decode(data).graph,parameters))]
    ensures decode(data).Decoded? ==>
              var callData := M.CallData(decode(data).graph,parameters);
              var observed := env.call(history,R.Call(self,callData));
              var raw := M.Spec(data,parameters,self,decode,env,history).raw;
              raw == (if !observed.codePresent then E.Aborted(E.Error(W.Encoded(C.InvalidTarget(0,self))))
                      else if observed.success then E.Produced(observed.data)
                      else if R.Exhausted(observed) then E.Aborted(E.Error(R.Signal()))
                      else E.Aborted(E.Error(W.Encoded(C.NodeCallFailed(0,self,callData,observed.data)))))

datatype Inner = NoGraph | Evaluated(out: Entry.Outcome, raw: E.Raw,
                                       evidence: M.Evidence, guards: seq<Guards.Record>)

  // One explicit modeled self-call observation connects the already-proved
  // encoded source wrapper to the public graph evaluation. Gas is observed,
  // and caller/static/memory projections remain separate EVM premises.

method CallReceipt(index: nat, target: R.Address, self: R.Address, data: seq<Byte>, selector: seq<Byte>,
                     env: R.Environment, history: seq<R.Request>) returns (ghost raw: E.Raw, after: seq<R.Request>)
    requires |selector| == 4 && index < Pow256(32)
    ensures after == C.Call(index,target,self,data,selector,env,history).history
    ensures var result := C.Call(index,target,self,data,selector,env,history).result;
            if result.Returned? then raw == E.Produced(result.data)
            else raw == E.Aborted(E.Error(W.Spec(result.error)))

method ProbeReceipt(target: R.Address, self: R.Address, data: seq<Byte>, selector: seq<Byte>, expected: seq<Byte>,
                      env: R.Environment, history: seq<R.Request>) returns (ghost raw: E.Raw, after: seq<R.Request>)
    requires |selector| == 4 && |expected| == 4
    requires |env.call(history,R.Call(target,data)).data|+96 < Pow256(32)
    ensures after == C.Probe(target,self,data,selector,expected,env,history).history
    ensures var result := C.Probe(target,self,data,selector,expected,env,history).result;
            if result.Returned? then raw == E.Produced(Encode(Bytes,Buffer(result.data)))
            else raw == E.Aborted(E.Error(W.Spec(result.error)))
    ensures raw.Produced? ==> Validate(Bytes,ExpressionEvaluationBridge.Narrow(raw.value)).Parsed?

